  try {
    let uncompressed = zlib.inflateSync(sData);
    streams.push(uncompressed.toString('latin1'));
  } catch(e) {
    // might not be flate
    streams.push(sData.toString('latin1'));
  }
  idx = eIdx + 9;
}
console.log('Found streams:', streams.length);

function cleanPdfText(str) {
  // simple extraction of string literals
  let res = '';
  let inParen = false;
  let cur = '';
