const buf = fs.readFileSync("LP3/Advanced_Linux_Programming.pdf");

let idx = 0;
let streams = [];
while (true) {
  let sIdx = buf.indexOf("stream\r\n", idx);
  let lenOffset = 8;
  if (sIdx === -1) {
    sIdx = buf.indexOf("stream\n", idx);
    lenOffset = 7;
  }
  if (sIdx === -1) break;
  let eIdx = buf.indexOf("endstream", sIdx);
  if (eIdx === -1) break;
  let sData = buf.slice(sIdx + lenOffset, eIdx);
  if (sData[sData.length - 1] === 10) sData = sData.slice(0, -1);
  if (sData[sData.length - 1] === 13) sData = sData.slice(0, -1);
  try {
    let uncompressed = zlib.inflateSync(sData);
    streams.push(uncompressed.toString("latin1"));
  } catch(e) {
    streams.push(sData.toString("latin1"));
  }
  idx = eIdx + 9;
}

function decodeStream(st) {
  let res = [];
  // match Tj and TJ
  let lines = st.split("\n");
  for (let l of lines) {
    let m = l.match(/\[(.*)\]\s*TJ/);
    if (m) {
      let parts = m[1].match(/\((?:[^()\\]|\\.)*\)/g);
      if (parts) {
        let str = parts.map(p => p.slice(1, -1).replace(/\\([()\\])/g, "$1")).join("");
        res.push(str);
      }
    } else {
      let m2 = l.match(/\(((?:[^()\\]|\\.)*)\)\s*Tj/);
      if (m2) {
        res.push(m2[1].replace(/\\([()\\])/g, "$1"));
      }
    }
  }
  return res.join(" ");
}

for (let i = 38; i <= 52; i++) {
  console.log("=== STREAM", i, "===");
  console.log(decodeStream(streams[i]));
}
