const zlib = require('zlib');
const buf = fs.readFileSync('LP3/Advanced_Linux_Programming.pdf');

let idx = 0;
let streams = [];
while (true) {
  let sIdx = buf.indexOf('stream\r\n', idx);
  let lenOffset = 8;
  if (sIdx === -1) {
    sIdx = buf.indexOf('stream\n', idx);
    lenOffset = 7;
  }
  if (sIdx === -1) break;
  let eIdx = buf.indexOf('endstream', sIdx);
  if (eIdx === -1) break;
  let sData = buf.slice(sIdx + lenOffset, eIdx);
  if (sData[sData.length - 1] === 10) sData = sData.slice(0, -1);
  if (sData[sData.length - 1] === 13) sData = sData.slice(0, -1);
  try {
    let uncompressed = zlib.inflateSync(sData);
    streams.push(uncompressed.toString('latin1'));
  } catch(e) {
    streams.push(sData.toString('latin1'));
  }
  idx = eIdx + 9;
}

function parsePdfStreamText(st) {
  let tokens = [];
  let pos = 0;
  while (pos < st.length) {
    if (st[pos] === '(') {
      let str = '';
      pos++;
      let depth = 1;
      while (pos < st.length) {
        if (st[pos] === '\\' && pos + 1 < st.length) {
          let next = st[pos+1];
          if (next >= '0' && next <= '7') {
            // octal
            let oct = st.substr(pos+1, 3);
            let match = oct.match(/^[0-7]{1,3}/);
            if (match) {
              str += String.fromCharCode(parseInt(match[0], 8));
              pos += 1 + match[0].length;
              continue;
            }
          }
          str += next;
          pos += 2;
        } else if (st[pos] === '(') {
          depth++;
          str += '(';
          pos++;
        } else if (st[pos] === ')') {
          depth--;
          if (depth === 0) {
            pos++;
            break;
          } else {
            str += ')';
            pos++;
          }
        } else {
          str += st[pos];
          pos++;
        }
      }
      tokens.push(str);
    } else {
      pos++;
    }
  }
  return tokens.join(' ');
}

for (let i = 38; i <= 52; i++) {
  console.log('=== STREAM ' + i + ' ===');
  console.log(parsePdfStreamText(streams[i]));
}
